Lemma merge_fb2 : forall (P : machine_state -> Prop) ra sp gp tp t2 s0 s1 a1 a2 a5 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
    t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem) (FROM n0 f0 l0 B0 b b' nb nb' : Z) (e e' : list (Z * Z)),
  (b + 8192 <= b' \/ b' + 8192 <= b)%Z -> (0 < b /\ b + 8192 <= 2^47)%Z -> (0 < b' /\ b' + 8192 <= 2^47)%Z ->
  (0 <= bsum e)%Z -> (0 <= bsum e')%Z -> (bsum e + bsum e' < 2^56)%Z -> (Z.of_nat (length e + length e') <= 1021)%Z ->
  (1 <= n0 < 2^63)%Z -> (0 < FROM)%Z -> (FROM + 32 <= b \/ b + 8192 <= FROM)%Z -> (FROM + 32 <= b' \/ b' + 8192 <= FROM)%Z ->
  rw_cells asegs m FROM [C8 (Z_to_bv 64 n0); C8 (Z_to_bv 64 f0); C8 (Z_to_bv 64 l0); C8 (Z_to_bv 64 B0)] ->
  rw_cells asegs m b [C8 (Z_to_bv 64 nb); C8 (Z_to_bv 64 (8192 + bsum e)); C8 (Z_to_bv 64 (Z.of_nat (length e)))] ->
  rw_cells asegs m b' [C8 (Z_to_bv 64 nb'); C8 (Z_to_bv 64 (8192 + bsum e')); C8 (Z_to_bv 64 (Z.of_nat (length e')))] ->
  mem_inv asegs m ->
  (forall (m' : mem) (t2' : word),
     munch [(b, b + 24); (b', b' + 24)]%Z m m' -> wmono asegs m m' -> mem_inv asegs m' ->
     rw_cells asegs m' FROM [C8 (Z_to_bv 64 n0); C8 (Z_to_bv 64 f0); C8 (Z_to_bv 64 l0); C8 (Z_to_bv 64 B0)] ->
     rw_cells asegs m' b [C8 (Z_to_bv 64 nb); C8 (Z_to_bv 64 (8192 + bsum (e ++ e'))); C8 (Z_to_bv 64 (Z.of_nat (length (e ++ e'))))] ->
     rw_cells asegs m' b' [C8 (Z_to_bv 64 nb'); C8 (Z_to_bv 64 8192); C8 (Z_to_bv 64 0)] ->
     evt asegs P (MS (mkR ra sp gp tp (Z_to_bv 64 b') (Z_to_bv 64 (Z.of_nat (length e') + Z.of_nat (length e))) t2' s0 s1
                          (Z_to_bv 64 FROM) a1 a2 (Z_to_bv 64 n0) (Z_to_bv 64 b) a5 (Z_to_bv 64 (-8192)) (Z_to_bv 64 8192)
                          s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                     F (Z_to_bv 64 0xa3388) fc None m' (seg_rom asegs))) ->
  evt asegs P (MS (mkR ra sp gp tp (Z_to_bv 64 b') (Z_to_bv 64 (Z.of_nat (length e') + Z.of_nat (length e))) t2 s0 s1
